`,e.jsxs(t.table,{children:[e.jsx(t.thead,{children:e.jsxs(t.tr,{children:[e.jsx(t.th,{children:"Workflow"}),e.jsx(t.th,{children:"Documented fact and exact source"}),e.jsx(t.th,{children:"Proposed acceptance, failure/recovery and persistence boundary"})]})}),e.jsxs(t.tbody,{children:[e.jsxs(t.tr,{children:[e.jsx(t.td,{children:"Preserve HDR evidence before display conversion"}),e.jsxs(t.td,{children:[e.jsx(t.a,{href:"https://openexr.com/en/latest/",children:"OpenEXR"})," distinguishes scene-linear HDR from display-ready image storage and supports multipart/multichannel metadata. Its October 2, 2026 3.5.2 notice recommends regenerating lossy-LJ2K files written by 3.5.0/3.5.1; the compatibility fallback does not replace that recommendation."]}),e.jsx(t.td,{children:"Preserve original channels/parts, compression/library version and display transform separately from the review PNG. Identify affected compression/version before regeneration; do not generalize this warning to every EXR. Installed library and file lineage remain unknown."})]}),e.jsxs(t.tr,{children:[e.jsx(t.td,{children:"Denoise without losing reference evidence"}),e.jsxs(t.td,{children:[e.jsx(t.a,{href:"https://www.openimagedenoise.org/",children:"OIDN overview and release history"})," documents C/C++ denoising of ray-traced beauty buffers, optionally albedo/normals, and hardware/driver-specific support. Release history records CPU cancellation fixes in 2.3.1 following 2.3.0 problems. Library license is Apache-2.0."]}),e.jsxs(t.td,{children:["Save noisy inputs, auxiliary-buffer provenance, filter settings and actual backend/version with the derivative. Do not treat a cleaner image as ground truth, or presume identical cancellation across versions. The ",e.jsx(t.a,{href:"https://github.com/RenderKit/oidn/blob/v2.3.1/README.md",children:"OIDN 2.3.1 API guide"})," distinguishes blocking execution from ",e.jsx(t.code,{children:"oidnExecuteFilterAsync"}),": synchronize with ",e.jsx(t.code,{children:"oidnSyncDevice"})," before reading output or releasing the filter. Async errors surface at synchronization. Returning false from the progress callback requests best-effort cancellation; only fulfilled cancellation raises ",e.jsx(t.code,{children:"OIDN_ERROR_CANCELLED"}),". The API does not guarantee cancellation. Preserve native errors and validate these paths in an unimplemented fixture; artifact durability remains unknown."]})]}),e.jsxs(t.tr,{children:[e.jsx(t.td,{children:"Submit shared binary assets"}),e.jsxs(t.td,{children:[e.jsx(t.a,{href:"https://help.perforce.com/helix-core/server-apps/cmdref/current/Content/CmdRef/p4_lock.html",children:"P4 lock, page labeled 2026.1"})," blocks other users' submissions, fails if another user holds the lock, and releases the lock when the owner submits. Omitting file arguments locks all open files in the default changelist."]}),e.jsx(t.td,{children:"Specify files/changelist explicitly; report contention rather than blindly retrying or forcing someone else's lock. A submission lock does not promise to prevent other users editing local files. Record actual submit result/revision separately from lock acquisition. Server topology, permissions and license entitlement remain project-specific."})]}),e.jsxs(t.tr,{children:[e.jsx(t.td,{children:"Keep navigation generation separate from runtime motion"}),e.jsxs(t.td,{children:[e.jsx(t.a,{href:"https://github.com/recastnavigation/recastnavigation",children:"Recast main README"})," separates Recast generation, Detour loading/path queries, DetourTileCache streaming and DetourCrowd movement/avoidance. Repository displays Zlib licensing."]}),e.jsxs(t.td,{children:["Retain generation parameters and navmesh artifact with query/crowd observations. A generated mesh or returned path alone does not prove traversability by the actual character controller. This README does not establish tile invalidation, cancellation, persistence compatibility or recovery. The ",e.jsx(t.a,{href:"/docs/engine-operation-contracts/#navigation-after-procedural-world-edits",children:"source-pinned navigation contract"})," now details query/status and tile-rebuild limits; execution and recovery remain unverified."]})]}),e.jsxs(t.tr,{children:[e.jsx(t.td,{children:"Remove physics bodies before destroying them"}),e.jsxs(t.td,{children:[e.jsx(t.a,{href:"https://jrouwe.github.io/JoltPhysics/",children:"Jolt architecture"})," documents CreateBody → AddBody → RemoveBody → DestroyBody; DestroyBody does not automatically remove a body from PhysicsSystem. Prepared batch additions can be finalized or aborted with the corresponding functions."]}),e.jsx(t.td,{children:"Track created/added/prepared states so cleanup chooses the matching operation. Batch-abort is not arbitrary simulation rollback. Preserve inputs/version and validate deterministic limits before replication claims; homepage determinism explicitly links qualifications. Exact build/license inventory and persistence compatibility remain unchecked here."})]}),e.jsxs(t.tr,{children:[e.jsx(t.td,{children:"Record bake settings alongside textures"}),e.jsxs(t.td,{children:[e.jsx(t.a,{href:"https://marmoset.co/toolbag/baking/",children:"Toolbag baking"})," lists cage/skew painting, isolated bake groups, UDIM/multiple texture sets, UV padding, bit depth and tangent-space/orientation choices. This is a mutable product feature page, not a scripting reference."]}),e.jsx(t.td,{children:"Persist source mesh revisions and bake settings with outputs; inspect seams/projection errors in the target renderer. A written texture is insufficient evidence that tangent conventions match. Headless API, job cancellation, transactional writes and license entitlement are unknown from this page."})]}),e.jsxs(t.tr,{children:[e.jsx(t.td,{children:"Scope simulated network failure"}),e.jsxs(t.td,{children:[e.jsx(t.a,{href:"https://docs.unity3d.com/Packages/com.unity.multiplayer.tools@2.2/manual/network-simulator.html",children:"Unity Multiplayer Tools 2.2 Network Simulator"})," exposes disconnects, lag spikes, loss and scripted scenarios through the UTP simulator pipeline. Page requirements: Editor 2022.2+, UTP 2.0+, NGO 1.1+."]}),e.jsx(t.td,{children:"Log preset/scenario timing and actual disconnect/reconnect state. Restore test configuration and verify application recovery separately; impairment removal is not game-state reconciliation. This does not establish coverage of arbitrary transports or real ISP behavior. Installed package combination and reproducibility remain untested."})]}),e.jsxs(t.tr,{children:[e.jsx(t.td,{children:"Supplement automated web accessibility checks"}),e.jsxs(t.td,{children:[e.jsx(t.a,{href:"https://accessibilityinsights.io/docs/web/overview/",children:"Accessibility Insights Web"})," combines automated FastPass checks with partially automated tab-stop inspection; Assessment targets WCAG 2.1 AA and includes manual/assisted tests."]}),e.jsx(t.td,{children:"Store page/build scope and reviewer results for keyboard traps, missing stops and ordering. Automated pass is not full conformance or native/canvas-game accessibility coverage. Extension version and project-specific applicable requirements remain unknown."})]}),e.jsxs(t.tr,{children:[e.jsx(t.td,{children:"Review multimedia redistribution separately from render success"}),e.jsxs(t.td,{children:[e.jsx(t.a,{href:"https://ffmpeg.org/legal.html",children:"FFmpeg legal"})," describes LGPL 2.1-or-later baseline and optional GPL parts causing GPL to apply to FFmpeg. ",e.jsx(t.a,{href:"https://www.fmod.com/licensing",children:"FMOD licensing"})," grants game-distribution permission per project and requires commercial project registration; its free indie tier is conditional."]}),e.jsx(t.td,{children:"Preserve FFmpeg build configuration/dependency notices and the project's FMOD entitlement before packaging. Neither an executable's name nor successful bank creation establishes redistribution rights. Do not describe LGPL as applying to every FFmpeg binary or free FMOD authoring as universal distribution permission. Account terms, bundled dependencies and actual eligibility require project review."})]})]})]}),`
